"""Authored Yogabase Jobs facade tests. This file is not generated by Microsoft Kiota.

The shapes pinned here are the ones the mirrored client OpenAPI document declares for the Jobs routes
(``x-yogabase-jobs`` and the four operations) and the product's gateway writes. The last tests hold each request
the authored client sends to the request the generated Kiota builder builds for the same operation.
"""

import hashlib
import json
import unittest

import httpx
from kiota_abstractions.authentication.anonymous_authentication_provider import AnonymousAuthenticationProvider
from kiota_http.httpx_request_adapter import HttpxRequestAdapter

from yogabase_client import (
    JOB_IDEMPOTENCY_CONFLICT,
    JOB_NOT_FOUND,
    JOB_PAYLOAD_TOO_LARGE,
    JOB_RESPONSE_INVALID,
    JOB_RESULT_DIGEST_MISMATCH,
    YOGABASE_JOB_TERMINAL_STATUSES,
    AsyncJobsClient,
    JobsClientOptions,
    YogabaseApiClient,
    YogabaseJobsError,
)

PROJECT = "11111111-1111-4111-8111-111111111111"
JOB = "5d0a8f0e-3c63-4d5e-9a0b-7c1f3a9e2b41"
GATEWAY = "https://apps.example.test"
JOBS = f"{GATEWAY}/v1/projects/{PROJECT}/jobs"


def job_document(**overrides: object) -> dict:
    document: dict = {
        "jobId": JOB,
        "jobType": "orders-create",
        "status": "Queued",
        "attempt": 0,
        "maxAttempts": 5,
        "progressPercent": 0,
        "cancellationRequested": False,
        "resultReference": None,
        "failureCode": None,
        "createdAt": "2026-10-03T05:00:00+00:00",
        "updatedAt": "2026-10-03T05:00:01+00:00",
        "completedAt": None,
    }
    document.update(overrides)
    return document


def json_response(request: httpx.Request, body: object, status: int = 200, headers: dict | None = None) -> httpx.Response:
    return httpx.Response(
        status,
        content=json.dumps(body).encode(),
        headers={"Content-Type": "application/json", **(headers or {})},
        request=request,
    )


def problem_response(request: httpx.Request, status: int, title: str, code: str, **extras: object) -> httpx.Response:
    # What ASP.NET Core writes for Results.Problem(statusCode, title, detail, extensions): the code and the
    # limits are top-level members beside type, title, status and traceId.
    body = {"type": "https://tools.ietf.org/html/rfc9110", "title": title, "status": status, "traceId": "00-trace", "code": code, **extras}
    return httpx.Response(status, content=json.dumps(body).encode(), headers={"Content-Type": "application/problem+json"}, request=request)


def sha256(content: bytes) -> str:
    return "sha256:" + hashlib.sha256(content).hexdigest()


def result_response(request: httpx.Request, content: bytes, digest: str | None, status: int = 200) -> httpx.Response:
    headers = {"Content-Type": "application/octet-stream", "Cache-Control": "private, no-store"}
    if digest is not None:
        headers["X-Yogabase-Content-Sha256"] = digest
    return httpx.Response(status, content=content, headers=headers, request=request)


class Recorder:
    """A mock transport that records each request's method, URL, headers and body."""

    def __init__(self, *responders: object) -> None:
        self.requests: list[httpx.Request] = []
        self.bodies: list[bytes] = []
        self._responders = list(responders)

    def __call__(self, request: httpx.Request) -> httpx.Response:
        self.requests.append(request)
        self.bodies.append(request.read())
        responder = self._responders.pop(0) if len(self._responders) > 1 else self._responders[0]
        return responder(request)  # type: ignore[operator]

    def client(self, **options: object) -> AsyncJobsClient:
        settings: dict = {"gateway_host": GATEWAY, "project_id": PROJECT, "access_token": "user-token"}
        settings.update(options)
        return AsyncJobsClient(http_client=httpx.AsyncClient(transport=httpx.MockTransport(self)), **settings)


class JobsSubmitTests(unittest.IsolatedAsyncioTestCase):
    async def test_submit_sends_the_exact_route_body_and_user_token_and_reads_the_accepted_job(self) -> None:
        recorder = Recorder(lambda request: json_response(request, job_document(), 202, {"Location": f"/v1/projects/{PROJECT}/jobs/{JOB}"}))
        async with recorder.client() as jobs:
            job = await jobs.submit(job_type="orders-create", idempotency_key="order-42", payload=b"hello", max_attempts=3)

        request = recorder.requests[0]
        self.assertEqual((request.method, str(request.url)), ("POST", JOBS))
        self.assertEqual(request.headers["Authorization"], "Bearer user-token")
        self.assertEqual(request.headers["Content-Type"], "application/json")
        # The member order and the names are the gateway's submission, which refuses any other member.
        self.assertEqual(
            recorder.bodies[0],
            b'{"jobType":"orders-create","idempotencyKey":"order-42","payloadBase64":"aGVsbG8=","maxAttempts":3}',
        )
        # The key rides in the body: the gateway reads no Idempotency-Key header on this route.
        self.assertNotIn("Idempotency-Key", request.headers)
        self.assertEqual(job.job_id, JOB)
        self.assertEqual(job.job_type, "orders-create")
        self.assertEqual(job.status, "Queued")
        self.assertEqual((job.attempt, job.max_attempts, job.progress_percent), (0, 5, 0))
        self.assertFalse(job.cancellation_requested)
        self.assertIsNone(job.result_reference)
        self.assertIsNone(job.failure_code)
        self.assertEqual(job.created_at, "2026-10-03T05:00:00+00:00")
        self.assertIsNone(job.completed_at)
        self.assertFalse(job.is_terminal)

    async def test_submit_omits_an_absent_or_empty_payload_and_an_unset_attempt_budget(self) -> None:
        recorder = Recorder(lambda request: json_response(request, job_document(jobType="emails-send"), 202))
        async with recorder.client() as jobs:
            await jobs.submit(job_type="emails-send", idempotency_key="k")
            await jobs.submit(job_type="emails-send", idempotency_key="k", payload=b"")
        # A job with no payload and one with an empty payload are the same job to the gateway.
        self.assertEqual(recorder.bodies, [b'{"jobType":"emails-send","idempotencyKey":"k"}'] * 2)

    async def test_a_retried_submit_is_the_same_request_on_the_wire_so_the_gateway_can_replay_it(self) -> None:
        recorder = Recorder(
            lambda request: json_response(request, job_document(), 202),
            lambda request: json_response(request, job_document(status="Running"), 202),
        )
        async with recorder.client() as jobs:
            first = await jobs.submit(job_type="orders-create", idempotency_key="order-42", payload=bytes([1, 2, 3]))
            replay = await jobs.submit(job_type="orders-create", idempotency_key="order-42", payload=bytes([1, 2, 3]))
        self.assertEqual(recorder.bodies[0], recorder.bodies[1])
        self.assertEqual(first.job_id, replay.job_id)
        # 202 again, whatever the job has become.
        self.assertEqual(replay.status, "Running")

    async def test_a_submit_at_exactly_the_inline_limit_is_sent_and_one_byte_more_is_refused_before_the_network(self) -> None:
        recorder = Recorder(lambda request: json_response(request, job_document(), 202))
        async with recorder.client() as jobs:
            await jobs.submit(job_type="orders-create", idempotency_key="k-max", payload=bytes(1_048_576))
            self.assertEqual(len(json.loads(recorder.bodies[0])["payloadBase64"]), 1_398_104)
            with self.assertRaises(ValueError):
                await jobs.submit(job_type="orders-create", idempotency_key="k-over", payload=bytes(1_048_577))
        self.assertEqual(len(recorder.requests), 1)

    async def test_a_malformed_submit_is_refused_before_the_network(self) -> None:
        recorder = Recorder(lambda request: json_response(request, job_document(), 202))
        base = {"job_type": "orders-create", "idempotency_key": "k"}
        cases: list[dict] = [
            {**base, "job_type": ""},
            {**base, "job_type": "   "},
            {**base, "job_type": " orders-create"},
            {**base, "job_type": "orders-create "},
            {**base, "job_type": "orders create"},
            {**base, "job_type": "orders/create"},
            {**base, "job_type": "orders\ncreate"},
            {**base, "job_type": "ordérs"},
            {**base, "job_type": "a" * 129},
            {**base, "idempotency_key": ""},
            {**base, "idempotency_key": "   "},
            {**base, "idempotency_key": " padded"},
            {**base, "idempotency_key": "padded "},
            {**base, "idempotency_key": "has\ncontrol"},
            {**base, "idempotency_key": "k" * 257},
            {**base, "max_attempts": 0},
            {**base, "max_attempts": 11},
            {**base, "max_attempts": 2.5},
            {**base, "max_attempts": True},
            {**base, "payload": "not bytes"},
        ]
        async with recorder.client() as jobs:
            for case in cases:
                with self.assertRaises((ValueError, TypeError), msg=repr(case)):
                    await jobs.submit(**case)
        self.assertEqual(recorder.requests, [])

    async def test_the_longest_job_type_and_idempotency_key_are_sent(self) -> None:
        recorder = Recorder(lambda request: json_response(request, job_document(jobType="a" * 128), 202))
        async with recorder.client() as jobs:
            await jobs.submit(job_type="a" * 128, idempotency_key="k" * 256)
        self.assertEqual(len(recorder.requests), 1)

    async def test_a_non_ascii_key_travels_as_valid_json(self) -> None:
        recorder = Recorder(lambda request: json_response(request, job_document(), 202))
        async with recorder.client() as jobs:
            await jobs.submit(job_type="orders-create", idempotency_key="주문-42")
        self.assertEqual(json.loads(recorder.bodies[0])["idempotencyKey"], "주문-42")


class JobsRefusalTests(unittest.IsolatedAsyncioTestCase):
    async def test_a_submit_the_gateway_refuses_surfaces_its_status_and_code(self) -> None:
        for status, code, title in (
            (409, JOB_IDEMPOTENCY_CONFLICT, "The idempotency key belongs to a different job request."),
            (422, "job_type_not_registered", "The job type is not registered."),
            (400, "job_request_invalid", "Invalid job request."),
            (403, "job_access_denied", "Job access denied."),
            (503, "job_unavailable", "Job persistence unavailable."),
        ):
            recorder = Recorder(lambda request, s=status, t=title, c=code: problem_response(request, s, t, c))
            async with recorder.client() as jobs:
                with self.assertRaises(YogabaseJobsError, msg=code) as raised:
                    await jobs.submit(job_type="orders-create", idempotency_key="k")
            error = raised.exception
            self.assertEqual((error.status, error.code, str(error)), (status, code, title))
            self.assertIsNone(error.limit_bytes)
            self.assertIsNone(error.max_body_bytes)
            self.assertEqual(error.problem["traceId"], "00-trace")

    async def test_a_payload_too_large_refusal_names_the_limits_it_carries(self) -> None:
        detail = "A job payload may be at most 1048576 bytes before base64 encoding, and the whole request body at most 8391225 bytes."
        recorder = Recorder(lambda request: problem_response(
            request, 413, "The job payload is too large.", JOB_PAYLOAD_TOO_LARGE, detail=detail, limitBytes=1_048_576, maxBodyBytes=8_391_225))
        async with recorder.client() as jobs:
            with self.assertRaises(YogabaseJobsError) as raised:
                await jobs.submit(job_type="orders-create", idempotency_key="k", payload=b"x")
        error = raised.exception
        self.assertEqual((error.status, error.code), (413, "job_payload_too_large"))
        self.assertEqual((error.limit_bytes, error.max_body_bytes), (1_048_576, 8_391_225))
        self.assertIn("8391225", str(error))

    async def test_a_bare_413_from_a_gateway_that_predates_the_named_refusal_reads_as_payload_too_large(self) -> None:
        recorder = Recorder(lambda request: httpx.Response(413, request=request))
        async with recorder.client() as jobs:
            with self.assertRaises(YogabaseJobsError) as raised:
                await jobs.submit(job_type="orders-create", idempotency_key="k")
        self.assertEqual((raised.exception.status, raised.exception.code), (413, "payload_too_large"))
        self.assertIsNone(raised.exception.limit_bytes)

    async def test_an_installation_without_jobs_answers_a_plain_not_found_that_is_not_job_not_found(self) -> None:
        recorder = Recorder(lambda request: httpx.Response(404, request=request))
        async with recorder.client() as jobs:
            with self.assertRaises(YogabaseJobsError) as raised:
                await jobs.get(JOB)
        self.assertEqual((raised.exception.status, raised.exception.code), (404, "not_found"))
        self.assertNotEqual(raised.exception.code, JOB_NOT_FOUND)

    async def test_limits_that_are_not_positive_whole_numbers_are_not_reported(self) -> None:
        recorder = Recorder(lambda request: problem_response(request, 413, "x", JOB_PAYLOAD_TOO_LARGE, limitBytes=-1, maxBodyBytes="8391225"))
        async with recorder.client() as jobs:
            with self.assertRaises(YogabaseJobsError) as raised:
                await jobs.submit(job_type="orders-create", idempotency_key="k")
        self.assertIsNone(raised.exception.limit_bytes)
        self.assertIsNone(raised.exception.max_body_bytes)

    async def test_a_redirect_is_not_followed_and_is_a_refusal(self) -> None:
        recorder = Recorder(lambda request: httpx.Response(302, headers={"Location": "https://elsewhere.example.test/"}, request=request))
        async with recorder.client() as jobs:
            with self.assertRaises(YogabaseJobsError) as raised:
                await jobs.get(JOB)
        self.assertEqual((raised.exception.status, raised.exception.code), (302, "request_failed"))
        self.assertEqual(len(recorder.requests), 1)


class JobsGetAndCancelTests(unittest.IsolatedAsyncioTestCase):
    async def test_get_reads_one_job_by_its_route_and_maps_every_field(self) -> None:
        document = job_document(
            status="Succeeded", attempt=2, maxAttempts=3, progressPercent=100,
            resultReference="object://invocation-payload/abc/def", failureCode="handler_retry", completedAt="2026-10-03T05:00:09.1234567+00:00",
        )
        recorder = Recorder(lambda request: json_response(request, document))
        async with recorder.client() as jobs:
            job = await jobs.get(JOB)
        request = recorder.requests[0]
        self.assertEqual((request.method, str(request.url)), ("GET", f"{JOBS}/{JOB}"))
        self.assertEqual(request.headers["Authorization"], "Bearer user-token")
        self.assertEqual(recorder.bodies[0], b"")
        self.assertEqual(
            (job.status, job.attempt, job.max_attempts, job.progress_percent, job.result_reference, job.failure_code, job.completed_at),
            ("Succeeded", 2, 3, 100, "object://invocation-payload/abc/def", "handler_retry", "2026-10-03T05:00:09.1234567+00:00"),
        )
        self.assertTrue(job.is_terminal)

    async def test_every_status_is_read_and_only_the_settled_ones_are_terminal(self) -> None:
        for status in ("Queued", "Running", "Succeeded", "Failed", "Cancelled", "DeadLettered"):
            recorder = Recorder(lambda request, s=status: json_response(request, job_document(status=s)))
            async with recorder.client() as jobs:
                job = await jobs.get(JOB)
            self.assertEqual(job.status, status)
            self.assertEqual(job.is_terminal, status in YOGABASE_JOB_TERMINAL_STATUSES, status)

    async def test_another_users_job_and_an_unknown_job_are_the_same_not_found_to_a_read_and_to_a_cancel(self) -> None:
        recorder = Recorder(lambda request: problem_response(request, 404, "Job not found.", JOB_NOT_FOUND))
        async with recorder.client() as jobs:
            for call in (jobs.get, jobs.cancel):
                with self.assertRaises(YogabaseJobsError) as raised:
                    await call(JOB)
                self.assertEqual((raised.exception.status, raised.exception.code), (404, "job_not_found"))

    async def test_cancel_posts_to_the_cancel_route_with_no_body_and_reads_the_job(self) -> None:
        recorder = Recorder(lambda request: json_response(request, job_document(status="Running", cancellationRequested=True)))
        async with recorder.client() as jobs:
            job = await jobs.cancel(JOB)
        request = recorder.requests[0]
        self.assertEqual((request.method, str(request.url)), ("POST", f"{JOBS}/{JOB}/cancel"))
        self.assertEqual(recorder.bodies[0], b"")
        self.assertNotIn("Content-Type", request.headers)
        # A running job is flagged and stopped by its worker, so the flag can be set while it still runs.
        self.assertTrue(job.cancellation_requested)
        self.assertEqual(job.status, "Running")

    async def test_a_job_id_that_is_not_a_non_empty_canonical_uuid_is_refused_before_the_network_on_every_route(self) -> None:
        recorder = Recorder(lambda request: json_response(request, job_document()))
        async with recorder.client() as jobs:
            for job_id in ("", "not-a-guid", "00000000-0000-0000-0000-000000000000", JOB.replace("-", ""), f"{JOB}/../x"):
                for call in (jobs.get, jobs.cancel, jobs.result):
                    with self.assertRaises(ValueError, msg=job_id):
                        await call(job_id)
        self.assertEqual(recorder.requests, [])

    async def test_the_access_token_provider_is_asked_for_each_call_and_an_empty_token_is_refused(self) -> None:
        issued = []

        async def provider() -> str:
            issued.append(len(issued) + 1)
            return f"token-{len(issued)}"

        recorder = Recorder(lambda request: json_response(request, job_document()))
        async with recorder.client(access_token=provider) as jobs:
            await jobs.get(JOB)
            await jobs.get(JOB)
        self.assertEqual([request.headers["Authorization"] for request in recorder.requests], ["Bearer token-1", "Bearer token-2"])

        empty = Recorder(lambda request: json_response(request, job_document()))
        async with empty.client(access_token=lambda: "") as jobs:
            with self.assertRaises(TypeError):
                await jobs.get(JOB)
        self.assertEqual(empty.requests, [])


class JobsResponseValidationTests(unittest.IsolatedAsyncioTestCase):
    async def test_a_job_the_route_does_not_declare_is_refused_not_guessed_at(self) -> None:
        cases: list[object] = [
            job_document(status="Paused"),
            job_document(status=1),
            job_document(status="queued"),
            job_document(maxAttempts=0),
            job_document(maxAttempts=11),
            job_document(attempt=-1),
            job_document(attempt=1.5),
            job_document(attempt=True),
            job_document(progressPercent=101),
            job_document(progressPercent=-1),
            job_document(jobId="not-a-guid"),
            job_document(jobId="00000000-0000-0000-0000-000000000000"),
            job_document(jobType="has space"),
            job_document(jobType=""),
            job_document(failureCode="Upper_Case"),
            job_document(resultReference="https://elsewhere.example/result"),
            job_document(resultReference="object://"),
            job_document(resultReference="object://with space"),
            job_document(cancellationRequested="false"),
            job_document(createdAt="yesterday"),
            job_document(completedAt="later"),
            [],
            None,
            "a string",
        ]
        for document in cases:
            recorder = Recorder(lambda request, d=document: json_response(request, d))
            async with recorder.client() as jobs:
                with self.assertRaises(YogabaseJobsError, msg=repr(document)) as raised:
                    await jobs.get(JOB)
            self.assertEqual((raised.exception.status, raised.exception.code), (502, JOB_RESPONSE_INVALID), repr(document))

        not_json = Recorder(lambda request: httpx.Response(200, content=b"not json", request=request))
        async with not_json.client() as jobs:
            with self.assertRaises(YogabaseJobsError) as raised:
                await jobs.get(JOB)
        self.assertEqual(raised.exception.code, JOB_RESPONSE_INVALID)

    async def test_a_member_this_client_does_not_know_is_ignored(self) -> None:
        recorder = Recorder(lambda request: json_response(request, {**job_document(), "futureMember": {"nested": True}}))
        async with recorder.client() as jobs:
            job = await jobs.get(JOB)
        self.assertEqual(job.job_id, JOB)
        self.assertFalse(hasattr(job, "futureMember"))


class JobsResultTests(unittest.IsolatedAsyncioTestCase):
    async def test_the_result_is_read_from_its_route_and_checked_against_the_digest_the_gateway_sent(self) -> None:
        for length in (1, 81_920, 300_001):
            content = bytes((index * 31 + length) % 251 for index in range(length))
            recorder = Recorder(lambda request, c=content: result_response(request, c, sha256(c)))
            async with recorder.client() as jobs:
                result = await jobs.result(JOB)
            request = recorder.requests[0]
            self.assertEqual((request.method, str(request.url)), ("GET", f"{JOBS}/{JOB}/result"))
            self.assertEqual(request.headers["Authorization"], "Bearer user-token")
            self.assertEqual(request.headers["Accept"], "application/octet-stream, application/problem+json")
            self.assertEqual(result.content, content)
            self.assertEqual(result.digest, sha256(content))

    async def test_a_result_that_does_not_hash_to_its_digest_is_not_returned(self) -> None:
        served = b"what the store held"
        recorder = Recorder(lambda request: result_response(request, served, sha256(b"what the job recorded")))
        async with recorder.client() as jobs:
            with self.assertRaises(YogabaseJobsError) as raised:
                await jobs.result(JOB)
        self.assertEqual((raised.exception.status, raised.exception.code), (502, JOB_RESULT_DIGEST_MISMATCH))
        self.assertNotIn("what the store held", str(raised.exception))

    async def test_a_result_without_a_well_formed_digest_is_not_trusted_even_if_its_bytes_are_right(self) -> None:
        content = b"hello"
        right = sha256(content)[len("sha256:"):]
        for digest in (
            None, "", "sha256:", f"SHA256:{right}", f"sha256:{right.upper()}", f"sha256:{right[:-1]}",
            f"sha256:{right}4", f"sha1:{right}", right, f"sha256:z{right[1:]}",
        ):
            recorder = Recorder(lambda request, d=digest: result_response(request, content, d))
            async with recorder.client() as jobs:
                with self.assertRaises(YogabaseJobsError, msg=repr(digest)) as raised:
                    await jobs.result(JOB)
            self.assertEqual((raised.exception.status, raised.exception.code), (502, JOB_RESPONSE_INVALID), repr(digest))

    async def test_a_result_with_two_digest_headers_is_not_trusted(self) -> None:
        content = b"hello"
        digest = sha256(content)
        recorder = Recorder(lambda request: httpx.Response(
            200,
            content=content,
            headers=[("Content-Type", "application/octet-stream"), ("X-Yogabase-Content-Sha256", digest), ("X-Yogabase-Content-Sha256", digest)],
            request=request,
        ))
        async with recorder.client() as jobs:
            with self.assertRaises(YogabaseJobsError) as raised:
                await jobs.result(JOB)
        self.assertEqual(raised.exception.code, JOB_RESPONSE_INVALID)

    async def test_a_result_larger_than_the_bound_is_refused_declared_or_streamed(self) -> None:
        declared = Recorder(lambda request: httpx.Response(
            200,
            content=b"\x01",
            headers={"X-Yogabase-Content-Sha256": sha256(b"\x01"), "Content-Length": str(16 * 1_048_576 + 1)},
            request=request,
        ))
        async with declared.client() as jobs:
            with self.assertRaises(YogabaseJobsError) as raised:
                await jobs.result(JOB)
        self.assertEqual(raised.exception.code, JOB_RESPONSE_INVALID)

        chunk = bytes(1_048_576)

        async def body():
            for _ in range(17):
                yield chunk

        streamed = Recorder(lambda request: httpx.Response(
            200, content=body(), headers={"X-Yogabase-Content-Sha256": sha256(chunk)}, request=request))
        async with streamed.client() as jobs:
            with self.assertRaises(YogabaseJobsError) as raised:
                await jobs.result(JOB)
        self.assertEqual(raised.exception.code, JOB_RESPONSE_INVALID)

    async def test_a_success_that_is_not_a_200_is_not_a_result(self) -> None:
        content = b"hello"
        recorder = Recorder(lambda request: result_response(request, content, sha256(content), 202))
        async with recorder.client() as jobs:
            with self.assertRaises(YogabaseJobsError) as raised:
                await jobs.result(JOB)
        self.assertEqual(raised.exception.code, JOB_RESPONSE_INVALID)

    async def test_a_result_the_gateway_refuses_surfaces_its_status_and_code_and_no_bytes(self) -> None:
        for status, code, title in (
            (409, "job_result_not_ready", "The job has not settled, so it has no result yet."),
            (404, "job_result_not_found", "Job result not found."),
            (502, "job_result_integrity_failed", "The stored result does not match what the job recorded."),
            (500, "job_result_reference_invalid", "The job's stored result is not its own."),
            (503, "job_unavailable", "Job persistence unavailable."),
        ):
            recorder = Recorder(lambda request, s=status, t=title, c=code: problem_response(request, s, t, c))
            async with recorder.client() as jobs:
                with self.assertRaises(YogabaseJobsError, msg=code) as raised:
                    await jobs.result(JOB)
            self.assertEqual((raised.exception.status, raised.exception.code, str(raised.exception)), (status, code, title))


class JobsClientConstructionTests(unittest.IsolatedAsyncioTestCase):
    @staticmethod
    def _idle_http() -> httpx.AsyncClient:
        return httpx.AsyncClient(transport=httpx.MockTransport(lambda request: httpx.Response(204, request=request)))

    async def test_the_gateway_host_is_an_origin_https_unless_it_is_a_loopback_host_that_was_allowed(self) -> None:
        http = self._idle_http()
        base = {"project_id": PROJECT, "access_token": "token", "http_client": http}
        for host in ("https://apps.example.test/not-an-origin", "https://user:pass@apps.example.test", "https://apps.example.test/?q=1", "http://apps.example.test", "http://localhost:5480"):
            with self.assertRaises(ValueError, msg=host):
                AsyncJobsClient(gateway_host=host, **base)
        with self.assertRaises(ValueError):
            AsyncJobsClient(gateway_host="http://apps.example.test", allow_insecure_loopback=True, **base)
        self.assertEqual(AsyncJobsClient(gateway_host="http://localhost:5480", allow_insecure_loopback=True, **base).gateway_host, "http://localhost:5480")
        self.assertEqual(AsyncJobsClient(gateway_host="http://127.0.0.1:5480", allow_insecure_loopback=True, **base).gateway_host, "http://127.0.0.1:5480")
        self.assertEqual(AsyncJobsClient(gateway_host="http://[::1]:5480", allow_insecure_loopback=True, **base).gateway_host, "http://[::1]:5480")
        self.assertEqual(AsyncJobsClient(gateway_host="https://apps.example.test/", **base).gateway_host, "https://apps.example.test")
        with self.assertRaises(TypeError):
            AsyncJobsClient(gateway_host="https://apps.example.test", project_id=PROJECT, access_token="", http_client=http)
        for project in ("not-a-guid", "00000000-0000-0000-0000-000000000000"):
            with self.assertRaises(ValueError, msg=project):
                AsyncJobsClient(gateway_host="https://apps.example.test", project_id=project, access_token="token", http_client=http)
        await http.aclose()

    async def test_options_and_keyword_settings_are_not_mixed(self) -> None:
        http = self._idle_http()
        options = JobsClientOptions("https://apps.example.test", PROJECT, "token")
        with self.assertRaises(TypeError):
            AsyncJobsClient(options, gateway_host="https://apps.example.test", http_client=http)
        client = AsyncJobsClient(options, http_client=http)
        self.assertEqual(client.project_id, PROJECT)
        await client.aclose()
        await http.aclose()

    async def test_a_client_it_created_uses_the_platform_trust_store_and_closes_it(self) -> None:
        from unittest import mock

        context = __import__("ssl").create_default_context()
        with mock.patch("yogabase_client._gateway.platform_ssl_context", return_value=context) as platform:
            client = AsyncJobsClient(gateway_host="https://apps.example.test", project_id=PROJECT, access_token="token")
        try:
            platform.assert_called_once_with()
            self.assertIs(client._channel._http._transport._pool._ssl_context, context)  # httpx 0.28.1 / httpcore 1.0.9, both pinned
        finally:
            await client.aclose()
        self.assertTrue(client._channel._http.is_closed)

    async def test_the_project_in_the_route_is_the_clients_own(self) -> None:
        other = "22222222-2222-4222-8222-222222222222"
        recorder = Recorder(lambda request: json_response(request, job_document()))
        async with recorder.client(project_id=other) as jobs:
            await jobs.get(JOB)
        self.assertEqual(str(recorder.requests[0].url), f"{GATEWAY}/v1/projects/{other}/jobs/{JOB}")


class JobsGeneratedBuilderEquivalenceTests(unittest.IsolatedAsyncioTestCase):
    """Each request the authored client sends is the request the generated builder builds for the operation."""

    @staticmethod
    def shape(request: httpx.Request, body: bytes | None = None) -> dict:
        content = body if body is not None else request.read()
        return {
            "url": str(request.url),
            "method": request.method,
            "headers": {name.lower(): value for name, value in request.headers.items()},
            "body": json.loads(content) if content else None,
        }

    async def generated(self, call: object) -> dict:
        captured: list[httpx.Request] = []

        def handler(request: httpx.Request) -> httpx.Response:
            captured.append(request)
            return httpx.Response(200, content=b"{}", headers={"Content-Type": "application/json"}, request=request)

        async with httpx.AsyncClient(transport=httpx.MockTransport(handler)) as http:
            adapter = HttpxRequestAdapter(AnonymousAuthenticationProvider(), http_client=http)
            adapter.base_url = GATEWAY
            try:
                await call(YogabaseApiClient(adapter))  # type: ignore[operator]
            except Exception:  # noqa: BLE001 - only the request is under test; the canned answer is not a job
                pass
        self.assertEqual(len(captured), 1)
        return self.shape(captured[0])

    async def authored(self, call: object) -> dict:
        recorder = Recorder(lambda request: httpx.Response(200, content=b"{}", headers={"Content-Type": "application/json"}, request=request))
        async with recorder.client() as jobs:
            try:
                await call(jobs)  # type: ignore[operator]
            except Exception:  # noqa: BLE001 - the canned answer is not a job
                pass
        self.assertEqual(len(recorder.requests), 1)
        return self.shape(recorder.requests[0], recorder.bodies[0])

    def assert_same(self, sent: dict, built: dict) -> None:
        self.assertEqual(sent["url"], built["url"])
        self.assertEqual(sent["method"], built["method"])
        self.assertEqual(sent["body"], built["body"])
        # The authored client accepts at least what the generated builder asks for.
        accepted = [part.strip() for part in sent["headers"]["accept"].split(",")]
        for wanted in (part.strip() for part in built["headers"]["accept"].split(",")):
            self.assertIn(wanted, accepted)

    async def test_submit_sends_the_request_the_generated_post_builder_builds(self) -> None:
        from yogabase_client.models.job_submit_request import JobSubmitRequest

        body = JobSubmitRequest()
        body.job_type = "orders-create"
        body.idempotency_key = "order-42"
        body.payload_base64 = "aGVsbG8="
        body.max_attempts = 3
        built = await self.generated(lambda api: api.v1.projects.by_project_id(PROJECT).jobs.post(body))
        sent = await self.authored(
            lambda jobs: jobs.submit(job_type="orders-create", idempotency_key="order-42", payload=b"hello", max_attempts=3)
        )
        self.assert_same(sent, built)
        self.assertEqual(sorted(sent["body"]), sorted(built["body"]))

    async def test_get_cancel_and_result_send_the_requests_the_generated_builders_build(self) -> None:
        from uuid import UUID

        job = UUID(JOB)
        self.assert_same(
            await self.authored(lambda jobs: jobs.get(JOB)),
            await self.generated(lambda api: api.v1.projects.by_project_id(PROJECT).jobs.by_job_id(job).get()),
        )
        self.assert_same(
            await self.authored(lambda jobs: jobs.cancel(JOB)),
            await self.generated(lambda api: api.v1.projects.by_project_id(PROJECT).jobs.by_job_id(job).cancel.post()),
        )
        self.assert_same(
            await self.authored(lambda jobs: jobs.result(JOB)),
            await self.generated(lambda api: api.v1.projects.by_project_id(PROJECT).jobs.by_job_id(job).result.get()),
        )


if __name__ == "__main__":
    unittest.main()
